import { defineCard } from "../define.js";

// EDHREC rank 20686.
// Rulings:
//   This ability isn't a mana ability. It uses the stack.
//   Only the first main phase in a turn is the "precombat main phase," even if additional main
//     phases are generated by some effect.
//   If the enchanted permanent's mana cost is {2}{W}{U}, this Aura's controller adds {C}{C}{W}{U}.
//     If its mana cost is {X}{G}, this Aura's controller adds {G}. If its mana cost is {W/U}{W/U},
//     this Aura's controller chooses whether to add {W}{W}, {W}{U}, or {U}{U}. The choice may be
//     different each time the ability resolves.
//   You get the mana whether you want it or not. If you don't spend it, it will disappear at the
//     end of the current step (or phase).
//
// `{ manaCostOf: "attached" }`: the enchanted permanent's mana cost as it is
// when the ability resolves, one symbol of two colours asked at a time.

const TEXT =
  "At the beginning of your first main phase, add mana equal to enchanted permanent's mana cost. (Mana cost includes color. If a mana symbol has multiple colors, choose one.)";

export default defineCard({
  name: "Elemental Resonance",
  manaCost: "{2}{G}{G}",
  colors: ["G"],
  types: ["enchantment"],
  subtypes: ["Aura"],
  text: `Enchant permanent\n${TEXT}`,
  targets: ["permanent"],
  triggered: [
    {
      trigger: { on: "step-begins", step: "precombat-main", who: "you" },
      targets: [],
      effect: { kind: "add-mana", mana: { manaCostOf: "attached" }, amount: 0 },
      resolve: null,
      text: TEXT,
    },
  ],
});
